def clear_region(canvas, top, left, bottom, right, replacement=" "):
    if not isinstance(canvas, (list, tuple)) or not canvas or any(not isinstance(row, str) or not row for row in canvas):
        raise ValueError("canvas must contain non-empty strings")
    width = len(canvas[0])
    if any(len(row) != width for row in canvas):
        raise ValueError("canvas must be rectangular")
    coordinates = (top, left, bottom, right)
    if any(isinstance(value, bool) or not isinstance(value, int) for value in coordinates):
        raise ValueError("coordinates must be integers")
    if not isinstance(replacement, str) or len(replacement) != 1:
        raise ValueError("replacement must be one character")
    if top < 0 or left < 0 or bottom < top or right < left or bottom >= len(canvas) or right >= width:
        raise ValueError("invalid rectangle")
    result = list(canvas)
    for row_index in range(top, bottom):
        row = list(result[row_index])
        for column_index in range(left, right + 1):
            row[column_index] = replacement
        result[row_index] = "".join(row)
    return result

